// Digital output: control an LED
const int LED_PIN = 9;  // any digital pin

void setup() {
  pinMode(LED_PIN, OUTPUT);  // configure as output
}

void loop() {
  digitalWrite(LED_PIN, HIGH);  // 5V on pin
  delay(500);
  digitalWrite(LED_PIN, LOW);   // 0V on pin
  delay(500);
}

const int LED_PIN = 13;
const int BTN_PIN = 2;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  // INPUT_PULLUP: pin reads HIGH when button not pressed
  // When button connects pin to GND, it reads LOW
  pinMode(BTN_PIN, INPUT_PULLUP);
  Serial.begin(115200);
}

void loop() {
  int state = digitalRead(BTN_PIN);

  // Logic is INVERTED with pull-up: LOW = pressed
  if (state == LOW) {
    digitalWrite(LED_PIN, HIGH);  // button pressed: LED on
    Serial.println("Button pressed");
  } else {
    digitalWrite(LED_PIN, LOW);   // button released: LED off
  }
}

void setup() {
  Serial.begin(115200);
  // A0-A5 are automatically input — no pinMode needed for analog
}

void loop() {
  int raw = analogRead(A0);               // 0 to 1023
  float voltage = raw * (5.0 / 1023.0);  // convert to volts
  float percent  = raw / 1023.0 * 100.0; // 0–100%

  Serial.print("Raw: "); Serial.print(raw);
  Serial.print("  Voltage: "); Serial.print(voltage, 2); Serial.print("V");
  Serial.print("  Pct: "); Serial.print(percent, 1); Serial.println("%");

  delay(200);
}

const int LED_PIN = 9;  // must be a PWM pin (~)

void setup() {
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  // Fade in
  for (int brightness = 0; brightness <= 255; brightness += 5) {
    analogWrite(LED_PIN, brightness);  // 0=off, 255=full on
    delay(10);
  }
  // Fade out
  for (int brightness = 255; brightness >= 0; brightness -= 5) {
    analogWrite(LED_PIN, brightness);
    delay(10);
  }
}
